import { EFFORT_LEVELS, MODEL, SUBAGENT_MODEL, VERSION, type Effort, loadConfig, saveConfig } from "./core/config.ts";
import { diagnosticsPath, verifyChain } from "./core/diagnostics.ts";
import { memoryPath, readMemory } from "./core/memory.ts";
import { listSessions } from "./core/session.ts";
import { listSkills } from "./core/skills.ts";

export interface CommandResult {
  kind: "text" | "clear" | "quit" | "intro" | "compact" | "resume" | "submit";
  text?: string;
  resumeId?: string;
}

export interface CommandDef {
  name: string;
  description: string;
}

export const COMMANDS: CommandDef[] = [
  { name: "help", description: "show commands and keybindings" },
  { name: "clear", description: "clear conversation and screen" },
  { name: "compact", description: "summarize history to free context" },
  { name: "effort", description: "set effort: low | medium | high | max" },
  { name: "model", description: "show model configuration" },
  { name: "yolo", description: "toggle auto-approve for all actions" },
  { name: "diagnostics", description: "diagnostics status + verify trace chain" },
  { name: "no-diagnostics", description: "opt out of diagnostic traces" },
  { name: "memory", description: "show persistent memory" },
  { name: "skills", description: "list saved skills" },
  { name: "sessions", description: "list recent sessions" },
  { name: "resume", description: "resume a session: /resume <id>" },
  { name: "usage", description: "token usage this session" },
  { name: "init", description: "generate an AGENTS.md for this project" },
  { name: "intro", description: "replay the startup animation" },
  { name: "quit", description: "exit glint" },
];

export function runCommand(
  input: string,
  ctx: { usage: { prompt: number; completion: number; total: number }; ctxTokens: number },
): CommandResult {
  const [cmd, ...rest] = input.slice(1).split(/\s+/);
  const arg = rest.join(" ").trim();
  const config = loadConfig();

  switch (cmd) {
    case "help":
      return {
        kind: "text",
        text: [
          `**glint v${VERSION}** — Glint Research`,
          "",
          ...COMMANDS.map((c) => `  **/${c.name}** — ${c.description}`),
          "",
          "  **!cmd** — run a shell command directly",
          "  **esc** — interrupt the agent · **ctrl+c ×2** — quit",
          "  **↑/↓** — input history · **ctrl+a/e/u/w** — line editing",
          "",
          "Skills become commands: save one and invoke it as /name.",
        ].join("\n"),
      };
    case "clear":
      return { kind: "clear" };
    case "compact":
      return { kind: "compact" };
    case "effort": {
      if (!arg) {
        return {
          kind: "text",
          text: `effort: **${config.effort}** (${EFFORT_LEVELS[config.effort].maxIterations} tool rounds)\noptions: ${Object.keys(EFFORT_LEVELS).join(" · ")}`,
        };
      }
      if (!(arg in EFFORT_LEVELS)) {
        return { kind: "text", text: `unknown effort "${arg}" — use: ${Object.keys(EFFORT_LEVELS).join(", ")}` };
      }
      saveConfig({ effort: arg as Effort });
      return {
        kind: "text",
        text: `effort set to **${arg}** (${EFFORT_LEVELS[arg as Effort].maxIterations} tool rounds per turn)`,
      };
    }
    case "model":
      return {
        kind: "text",
        text: `agent: **${MODEL}**\nsubagent: **${SUBAGENT_MODEL}**\nprovider: Groq (free tier) — $0.00, always`,
      };
    case "yolo": {
      const next = !config.yolo;
      saveConfig({ yolo: next });
      return {
        kind: "text",
        text: next
          ? "yolo **on** — all tool actions auto-approved. Live dangerously."
          : "yolo **off** — shell commands and writes ask first.",
      };
    }
    case "diagnostics": {
      if (!config.diagnostics) {
        saveConfig({ diagnostics: true });
        return { kind: "text", text: "diagnostics **enabled** — traces resume." };
      }
      const check = verifyChain();
      return {
        kind: "text",
        text: [
          `diagnostics: **on** (local-only, never leaves this machine)`,
          `file: ${diagnosticsPath()}`,
          `records today: ${check.records} · chain integrity: ${check.ok ? "✓ intact" : `✗ BROKEN at record ${check.brokenAt}`}`,
          `each record is SHA-256 chained to the previous — tampering is detectable.`,
          `opt out: /no-diagnostics`,
        ].join("\n"),
      };
    }
    case "no-diagnostics":
      saveConfig({ diagnostics: false });
      return {
        kind: "text",
        text: "diagnostics **disabled** — no further traces will be written. Re-enable with /diagnostics.",
      };
    case "memory": {
      const mem = readMemory();
      return {
        kind: "text",
        text: mem
          ? `**memory** (${memoryPath()}):\n\n${mem}`
          : `memory is empty — ask me to remember something, or I'll save useful facts as we work. (${memoryPath()})`,
      };
    }
    case "skills": {
      const skills = listSkills();
      return {
        kind: "text",
        text:
          skills.length > 0
            ? `**skills:**\n${skills.map((s) => `  /${s.name} — ${s.description}`).join("\n")}`
            : 'no skills yet — ask me to "save this as a skill called X" after a task.',
      };
    }
    case "sessions": {
      const sessions = listSessions();
      return {
        kind: "text",
        text:
          sessions.length > 0
            ? `**recent sessions** (resume with /resume <id>):\n${sessions
                .map((s) => `  ${s.id} · ${s.updated?.slice(0, 16).replace("T", " ")} · ${s.messages} msgs · ${s.title}`)
                .join("\n")}`
            : "no saved sessions yet.",
      };
    }
    case "resume":
      if (!arg) return { kind: "text", text: "usage: /resume <id> — see /sessions" };
      return { kind: "resume", resumeId: arg };
    case "usage":
      return {
        kind: "text",
        text: `session tokens — prompt: **${fmt(ctx.usage.prompt)}** · completion: **${fmt(ctx.usage.completion)}** · total: **${fmt(ctx.usage.total)}**\ncontext now: ~${fmt(ctx.ctxTokens)} tokens · cost: **$0.00** (Groq free tier)`,
      };
    case "init":
      return {
        kind: "submit",
        text: "Inspect this repository (list the root, read the key config/build files) and write a concise AGENTS.md at the repo root: what the project is, the exact commands to build/test/run it, code conventions you can infer, and any gotchas. Keep it under 60 lines. If AGENTS.md already exists, improve it instead.",
      };
    case "intro":
      return { kind: "intro" };
    case "quit":
    case "exit":
      return { kind: "quit" };
    default:
      return { kind: "text", text: `unknown command: /${cmd} — try /help` };
  }
}

function fmt(n: number): string {
  return n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n);
}
